package com.yeyamo_mobile.api.booking_service.infrastructure.outbox;import java.time.Instant;import java.util.concurrent.TimeUnit;import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;import org.springframework.kafka.core.KafkaTemplate;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Component;import org.springframework.transaction.annotation.Transactional;
@Component@ConditionalOnProperty(name="booking.outbox.enabled",havingValue="true",matchIfMissing=true)public class BookingOutboxPublisher{private final BookingOutboxRepository repo;private final KafkaTemplate<String,String>kafka;public BookingOutboxPublisher(BookingOutboxRepository r,KafkaTemplate<String,String>k){repo=r;kafka=k;}@Scheduled(fixedDelayString="${booking.outbox.delay-ms:1000}")@Transactional public void publish(){for(var e:repo.findTop100ByPublishedAtIsNullOrderByOccurredAtAsc()){try{kafka.send(e.targetTopic,e.aggregateId,e.payload).get(5,TimeUnit.SECONDS);e.publishedAt=Instant.now();e.lastError=null;}catch(Exception x){e.attempts++;e.lastError=shorten(x.getMessage());}repo.save(e);}}private String shorten(String s){if(s==null)return"Kafka publication failed";return s.length()>1000?s.substring(0,1000):s;}}
